def solution(input_str):
    """
    Solves the game theory problem where players play on an n x m matrix.
    The winner is determined by XORing values at positions where (r + c) is even.
    """
    lines = input_str.strip().split('\n')
    idx = 0

    t = int(lines[idx])
    idx += 1
    results = []

    for _ in range(t):
        n, m = map(int, lines[idx].split())
        idx += 1

        if idx + n > len(lines):
            break

        xor_val = 0
        for r in range(n):
            row = list(map(int, lines[idx].split()))
            idx += 1
            for c in range(m):
                # XOR values where (r + c) is even
                if (r + c) % 2 == 0:
                    xor_val ^= row[c]

        if xor_val > 0:
            results.append("Ashish")
        else:
            results.append("Jeel")

    return '\n'.join(results)

