from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    operations = []
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        operations.append((parts[0], parts[1], parts[2]))

    min_time = [-1] * (m + 1)
    min_time[0] = 0

    queue = deque([0])

    current_time = 0
    while queue and current_time < n:
        current_time += 1

        t, x_prime, y_limit = operations[current_time - 1]
        x = x_prime / 100000.0

        new_queue = deque()

        for j in range(m + 1):
            k = j
            if min_time[k] == -1:
                continue

            for _ in range(y_limit + 1):
                if min_time[k] < current_time:
                    new_queue.append(k)

                if _ >= y_limit:
                    break

                if t == 1:
                    next_k = math.ceil(k + x)
                else:
                    next_k = math.ceil(k * x)

                if next_k <= m and min_time[next_k] == -1 and min_time[k] + 1 > min_time[next_k]:
                    new_queue.append(next_k)

        for j in range(m + 1):
            if min_time[j] == -1 and queue and queue[0] == j:
                min_time[j] = current_time

        visited_this_step = set()

        for j in range(m + 1):
            if j not in visited_this_step:
                visited_this_step.add(j)
                k = j
                can_reach = False

                for _ in range(y_limit + 1):
                    if can_reach:
                        break

                    if min_time[k] != -1 and min_time[k] == current_time:
                        can_reach = True

                    if _ >= y_limit:
                        break

                    if t == 1:
                        next_k = k + math.ceil(x)
                    else:
                        next_k = math.ceil(k * x)

                    if next_k <= m and min_time[next_k] == -1:
                        min_time[next_k] = current_time
                        can_reach = True

                    k = next_k

        queue = deque([j for j in range(m + 1) if min_time[j] == current_time])

    result = []
    for j in range(1, m + 1):
        result.append(str(min_time[j]))

    return '\n'.join(result) + '\n'

