def solution(input_str):
    MOD = 1000000007

    k, w = map(int, input_str.strip().split())

    # For w=1, it's k*(k-1) - but input constraints say w>=2
    # For larger w, the pattern is: k^w + (k-1)*k^(w-1) - (strings with only 2 consecutive same chars)
    # Simplified: k^w + k^(w-1)*(k-1) = k^(w-1) * (k + k - 1) = k^(w-1) * (2k-1)

    if w == 1:
        # Special case (though input says w>=2)
        return str((k * (k - 1) % MOD) + "\n")

    # Calculate k^(w-1) * (2k-1) % MOD
    result = (pow(k, w - 1, MOD) * (2 * k - 1)) % MOD

    return str(result + "\n")

