            suffixes = []
            for j in range(1, len(year_str) + 1):
                suffixes.append(year_str[-j:])

            suffixes.sort(key=lambda x: (len(x), x))

            for s in suffixes:
                if s not in used_suffixes:
                    used_suffixes.add(s)
