    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    # Build MST
    edge_in_mst = [False] * m
    count = 0
    adj = [[] for _ in range(n)]

    for a, b, e, idx in sorted_edges:
        if union(a, b):
            edge_in_mst[idx] = True
            count += 1
            adj[a].append((b, e))
            adj[b].append((a, e))

    # If all edges are in MST (tree case), nothing to output
    if count == n - 1:
        return ""

    # Binary lifting setup for LCA and max edge queries
    LOG = 19  # 2^19 > 100000
    parent_lca = [[-1] * LOG for _ in range(n)]
    depth = [-1] * n
    max_on_path = [[0] * LOG for _ in range(n)]
    visited = [False] * n

    def dfs(u, p, d):
        visited[u] = True
        depth[u] = d
        parent_lca[u][0] = p

        for v, w in adj[u]:
            if v != p:
                max_on_path[v][0] = w
                dfs(v, u, d + 1)

    dfs(0, -1, 0)

    # Build binary lifting table
    for j in range(1, LOG):
        for i in range(n):
            if parent_lca[i][j - 1] != -1:
                parent_lca[i][j] = parent_lca[parent_lca[i][j - 1]][j - 1]
                max_on_path[i][j] = max(max_on_path[i][j - 1],
                                       max_on_path[parent_lca[i][j - 1]][j - 1])

    def query_path_max(u, v):
        if depth[u] < depth[v]:
            u, v = v, u

        diff = depth[u] - depth[v]
        w = 0
        for j in range(LOG):
            if diff & (1 << j):
                w = max(w, max_on_path[u][j])
                u = parent_lca[u][j]

        if u == v:
            return w

        for j in range(LOG - 1, -1, -1):
            if parent_lca[u][j] != parent_lca[v][j]:
                w = max(w, max_on_path[u][j], max_on_path[v][j])
                u = parent_lca[u][j]
                v = parent_lca[v][j]

        w = max(w, max_on_path[u][0], max_on_path[v][0])
        return w

    # Process non-MST edges
    results = []
