    polygon = [tuple(map(float, line.split())) for line in lines[1:n+1]]
    f_values = [int(line) for line in lines[n+1:n+1+q]]

    def area(pts):
        s = 0.0
        sz = len(pts)
        for i in range(sz):
            s += pts[i][0] * pts[(i+1)%sz][1] - pts[i][1] * pts[(i+1)%sz][0]
        return abs(s) / 2.0

    def split(f):
        L, R = [], []
        for i in range(n):
            x1, y1 = polygon[i]
            x2, y2 = polygon[(i+1)%n]
            l1 = x1 < f; l2 = x2 < f
            r1 = not l1; r2 = not l2

            if l1 and l2:
                L.append((x1,y1)); L.append((x2,y2))
            elif r1 and r2:
                R.append((x1,y1)); R.append((x2,y2))
            elif l1 and r2:
                t = (f - x1)/(x2 - x1)
                y = y1 + t * (y2 - y1)
                L.append((x1, y1)); L.append((f, y))
                R.append((f, y)); R.append((x2, y2))
            elif r1 and l2:
                t = (f - x1)/(x2 - x1)
                y = y1 + t * (y2 - y1)
                R.append((x1, y1)); R.append((f, y))
                L.append((f, y)); L.append((x2, y2))
        return L, R

    def reflect(pts, f):
        return [(2*f - x, y) for x, y in pts]

    results = []
    for f in f_values:
        L, R = split(f)
        AR = area(R)
        if not L:
            results.append(f"{AR:.10f}")
        elif not R:
            AL = area(reflect(L, f))
            results.append(f"{AL:.10f}")
        else:
            AL = area(reflect(L, f))
            # Account for union area
            results.append(f"{(AR + AL):.10f}")

    return '\n'.join(results)

