        return "Borna\n"

    def angle(p):
        return math.atan2(p[1], p[0])

    angles = sorted([angle(p) for p in points])
    m = len(angles)

    max_gap = 0.0
    for i in range(m):
        start = angles[i]
        end = angles[(i + 1) % m]
        if i == m - 1:
            gap = end - start + 2 * math.pi  # account for wrap-around
        else:
            gap = end - start
        max_gap = max(max_gap, gap)

    # If all points fit in a half-plane (max gap >= π), Borna wins
    return "Borna\n" if max_gap >= math.pi else "Ani\n"

