        adj = defaultdict(list)
        for pair in nodes:
            adj[pair[0]].append(pair[1])
            adj[pair[1]].append(pair[0])

        indegree = {node: 0 for node in nodes}
        for pair in nodes:
            for neighbor in adj[pair[0]]:
                if neighbor in indegree:
                    indegree[neighbor] += 1

        queue = [node for node in nodes if indegree[node] == 0]
        result = []

        while queue:
            u = queue.pop(0)
            result.append(u)
            for neighbor in adj[u]:
                indegree[neighbor] -= 1
                if indegree[neighbor] == 0:
                    queue.append(neighbor)

        if len(result) != len(nodes):
            return None
        return result

    nodes_rows = list(set(i for i, _ in lt_edges))
    nodes_cols = list(set(j for _, j in lt_edges))

    topo_r = topo_sort(nodes_rows)
    topo_c = topo_sort(nodes_cols)

