        u, v = map(int, lines[i + 1].split())
        edge_list.append((u, v))
        adj[u].append(v)
        adj[v].append(u)

    # Find bridges
    disc = [-1] * (n + 1)
    low = [-1] * (n + 1)
    timer = 0
    has_bridge = False

    parent = {}

    def dfs_b(u, p):
        nonlocal timer, has_bridge
        disc[u] = low[u] = timer
        timer += 1
        parent[u] = p

        for v in adj[u]:
            if v == p:
                continue
            if disc[v] != -1:
                low[u] = min(low[u], disc[v])
            else:
                dfs_b(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    has_bridge = True

    for i in range(1, n + 1):
        if disc[i] == -1:
            dfs_b(i)

    if has_bridge:
        return '0\n'

    # Process order using DFS - get vertices in post order
    proc_order = []
    visited = [False] * (n + 1)

    def dfs_proc(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]:
                dfs_proc(v)
        proc_order.append(u)

    dfs_proc(1)

    # Build mapping from vertex to index in processing order
    order_map = {node: i for i, node in enumerate(proc_order)}

    # Orient each edge
    result = []
