def solution(inp):
    lines = inp.strip().split('\n')
    n, m = map(int, lines[0].split())
    edges = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        edges.append((int(parts[0]), int(parts[1])))

    def cross(e1, e2):
        a1, b1 = e1
        a2, b2 = e2

        # Normalize edges so first endpoint < second
        if a1 > b1:
            a1, b1 = b1, a1
        if a2 > b2:
            a2, b2 = b2, a2

        # Define clockwise arc from start to end
        def clockwise_arc(start, end, n):
            if start < end:
                return (start, end)  # No wrap
            else:
                return (end, start)  # Wraps around

        arc1 = clockwise_arc(a1, b1, n)
        arc2 = clockwise_arc(a2, b2, n)

        start1, end1 = arc1
        start2, end2 = arc2

        # Check if segments overlap in a crossing way
        # Two edges cross if one endpoint of e2 is in arc of e1
        # but endpoint of e1 is not in arc of e2 (or vice versa)

        def in_arc(start, end, val):
            if start < end:
                return start < val < end
            else:
                return val > start or val < end

        a2_in_1 = in_arc(start1, end1, a2)
        b2_in_1 = in_arc(start1, end1, b2)
        a1_in_2 = in_arc(start2, end2, a1)
        b1_in_2 = in_arc(start2, end2, b1)

        # Check if exactly one endpoint of each edge is in the other's arc
        crosses_e2 = a2_in_1 != b2_in_1
        crosses_e1 = a1_in_2 != b1_in_2

        # They cross if both conditions are true
        return crosses_e2 and crosses_e1

    # Build conflict graph - edges that cross must have different sides
    adj = [[] for _ in range(m)]

    for i in range(m):
        for j in range(i + 1, m):
            if cross(edges[i], edges[j]):
                adj[i].append(j)
                adj[j].append(i)

    # Try to 2-color the conflict graph
    color = [-1] * m
    possible = True

    for start in range(m):
        if color[start] == -1:
            color[start] = 0
            queue = [start]
            idx = 0
            while idx < len(queue):
                u = queue[idx]
                idx += 1
                for v in adj[u]:
                    if color[v] == -1:
                        color[v] = 1 - color[u]
                        queue.append(v)
                    elif color[v] == color[u]:
                        possible = False
                        break
                if not possible:
                    break
            if not possible:
                break

    if not possible:
        return "Impossible\n"

    result = []
    for c in color:
        if c == 0:
            result.append('i')
        else:
            result.append('o')

    return ''.join(result) + '\n'


