from copy import copy

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "-1\n"

    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    counts = Counter(a)

    def check(m):
        """Check if we can form exactly m valid prairie partitions"""
        remaining = dict(counts)

        for _ in range(m):
            # Get sorted keys (descending)
            sorted_keys = sorted(remaining.keys(), reverse=True)
            if not sorted_keys:
                return False

            # Try each element in descending order as potential r
            found_partition = False
            for elem in sorted_keys:
                k = elem.bit_length() - 1
                r_val = elem

                # Valid if r <= 2^k (i.e., elem <= 2^k)
                # Actually, we need r in [1, 2^k] and here r = elem
                # But we verify this condition after bit_length calc
                if r_val < 1:
                    continue
                if r_val > (1 << k):
                    continue

                # Try to form partition with this r
                test_remaining = copy(remaining)

                # Check if r is available
                if test_remaining[r_val] > 0:
                    test_remaining[r_val] -= 1
                    if test_remaining[r_val] == 0:
                        del test_remaining[r_val]

                    # Check if powers 2^0, 2^1, ..., 2^(k-1) are available
                    powers_ok = True
                    for p in range(k):
                        req = 1 << p
                        if test_remaining.get(req, 0) > 0:
                            test_remaining[req] -= 1
                            if test_remaining[req] == 0:
                                del test_remaining[req]
                        else:
                            powers_ok = False
                            break

                    if powers_ok:
                        remaining = test_remaining
                        found_partition = True
                        break

            if not found_partition:
                return False

        return True

    # Try each possible m
    valid = []
    for m in range(1, n + 1):
        if check(m):
            valid.append(m)

    if not valid:
        return "-1\n"
    return ' '.join(map(str, valid)) + '\n'

