def main():
    line = sys.stdin.readline()
    n, m = map(int, line.split())

    # Find divisors
    def get_divisors(x):
        divs = []
        for i in range(1, int(x**0.5) + 1):
            if x % i == 0:
                divs.append(i)
                if i != x // i:
                    divs.append(x // i)
        return sorted(divs)

    n_divs = get_divisors(n)
    m_divs = get_divisors(m)

    def check_vertical_period(r):
        if r == n:
            return True
        # Check if AM[i][j] = AM[i+r][j] for various i, j
        # Test a few positions: (1, 1), (1, m)
        if n > 3 * r:  # ensure enough space
            # Compare AM[1][1] with AM[1+r][1]
            # Compare AM[1][m] with AM[1+r][m]
            res = query(r, 1, 1, 1, r+1, 1)
            res = query(r, 1, 1, m, r+1, m)
            return not (res == 0)  # 1 if equal
        else:
            # Not enough space for standard testing
            return True  # assume period exists

    def check_horizontal_period(c):
        if c == m:
            return True
        # Check if AM[i][j] = AM[i][j+c] for various i, j
        if m > 3 * c:
            # Compare AM[1][1] with AM[1][1+c]
            # Compare AM[n][m] with AM[n][m-c]
            res = query(c, 1, 1, 1, 1, c+1)
            res = query(c, 1, n, 1, n, m-c+1)
            return not (res == 0)
        else:
            return True

    ans = 0
    for r in n_divs:
        for c in m_divs:
            if check_vertical_period(r) and check_horizontal_period(c):
                ans += 1

    print(f"! {ans}")
    sys.stdout.flush()

